def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split pre-release (everything after first '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(int(x) for x in version_part.split('.'))

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_ids = prerelease_part.split('.')
        else:
            prerelease_ids = None

        return version_nums, prerelease_ids

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1,)

        # Pre-release sorts before release
        key = [0]
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers sort numerically and before non-digit
                key.append((0, int(identifier)))
            else:
                # Non-digit identifiers sort by ASCII after all-digit
                key.append((1, identifier))
        return tuple(key)

    def sort_key(item):
        version_str, original_index = item
        version_nums, prerelease_ids = parse_version(version_str)
        return (version_nums, prerelease_key(prerelease_ids), original_index)

    # Create list with original indices to maintain input order for equal precedence
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort by the key function
    sorted_versions = sorted(indexed_versions, key=sort_key)

    # Return just the version strings
    return [v for v, _ in sorted_versions]

